---
-- These functions return a table of enemies for the provided parameters.
--
-- Enemies functions are the profile API table `enemies` (br.api.profile.enemies); profiles use it by name.
--
-- After defining enemies you would place the below functions in the main profile loop to populate and update the enemy tables.
--
-- Once done you can use variables such as these examples, you can also get count of enemies but just added a `#` in front of the variable name:
--
-- * `enemies.yards8` - Returns all enemies around player in 8yrds, generated by function enemies.get(8)
--
-- * `enemies.yards8t` - Returns all enemies around target in 8yrds, generated by function enemies.get(8,"target")
--
-- * `enemies.yards8tnc` - Returns all units around target in 8yrds, generated by function enemies.get(8,"target",true)
--
-- * `enemies.yards8tncf` - Returns all units the target is facing in 8yrds, generated by function enemies.get(8,"target",true,true)
--
-- For enemies in a cone it is the same as above but you use the `c` tag instead of `t`. Ex function: enemies.cone.get(8, 90) (range, angle)
--
-- For enemies in a rectangle it is the same as above but you use the `r` tag instead of `t`. Ex function: enemies.rect.get(8, 5) (range, width)
--
-- @module enemies

local _, br = ...
br.api.build.enemies = function(api)
    local enemies = api.enemies
    -- enemies.yards8, enemies.yards8t, ...: this tick's lists, kept by the enemies engine
    setmetatable(enemies, { __index = br.engines.enemiesEngine.lists })
    enemies.cone = enemies.cone or {}
    enemies.rect = enemies.rect or {}

    --- True when any unit in a list passes a check. Instead of looping in the profile, write the
    -- check once (a function of one unit) and pass it with the list.
    -- @function enemies.any
    -- @tparam table list A list of units, such as enemies.yards10
    -- @tparam function check Returns true for a unit that counts, as check(thisUnit)
    -- @treturn boolean
    -- @usage if enemies.any(enemies.yards10, function(thisUnit) return debuff.demoralizingRoar.refresh(thisUnit) end) then
    enemies.any = function(list, check)
        for i = 1, #list do
            if check(list[i]) then return true end
        end
        return false
    end

    --- The enemies in the player's frontal cone, by the server's rule (see getEnemiesInCone)
    -- @function enemies.cone.get
    -- @number range How far the cone reaches, in yards
    -- @number angle The cone's full angle, in degrees (the spell's ConeDegrees)
    -- @bool checkNoCombat Count units not in combat too
    -- @treturn table The units, the same table as enemies.yards<range>c
    -- @treturn number How many
    enemies.cone.get = function(range, angle, checkNoCombat)
        local count, units = br.engines.enemiesEngineFunctions:getEnemiesInCone(range, angle, checkNoCombat)
        -- The list kept as enemies.yards<range>c: the engine reuses its table on the next call
        return br.functions.misc:setEnemiesVariable("player", range, checkNoCombat, false, "c", units, count), count
    end

    --- How many units in a list pass a check.
    -- @function enemies.count
    -- @tparam table list A list of units, such as enemies.yards8
    -- @tparam function check Returns true for a unit that counts, as check(thisUnit)
    -- @treturn number
    -- @usage if enemies.count(enemies.yards8, function(thisUnit) return unit.ttd(thisUnit) > 10 end) >= 3 then
    enemies.count = function(list, check)
        local count = 0
        for i = 1, #list do
            if check(list[i]) then count = count + 1 end
        end
        return count
    end

    --- The first unit in a list that passes a check, to cast on it; nil when none does.
    -- @function enemies.first
    -- @tparam table list A list of units, such as enemies.yards5
    -- @tparam function check Returns true for a unit that counts, as check(thisUnit)
    -- @return The unit, or nil
    -- @usage local thisUnit = enemies.first(enemies.yards5, needsLacerate)
    -- if thisUnit and cast.able.lacerate(thisUnit) then cast.lacerate(thisUnit) end
    enemies.first = function(list, check)
        for i = 1, #list do
            local thisUnit = list[i]
            if check(thisUnit) then return thisUnit end
        end
        return nil
    end

    --- Returns a table of all enemies around unit for given range, combat situation, and facing
    -- @function enemies.get
    -- @number range The range to check for enemies
    -- @string unit The unit to check for enemies around
    -- @bool checkNoCombat Check for enemies even if not in combat
    -- @bool facing Check if enemies are facing unit
    -- @treturn table
    -- @treturn number How many
    enemies.get = function(range, unit, checkNoCombat, facing)
        if unit == nil then unit = "player" end
        if checkNoCombat == nil then checkNoCombat = false end
        if facing == nil then facing = false end
        local enemyTable = br.engines.enemiesEngineFunctions:getEnemies(unit, range, checkNoCombat, facing)
        -- Build enemies.yards variable
        br.functions.misc:setEnemiesVariable(unit, range, checkNoCombat, facing, "", enemyTable)
        -- Backwards compatability for old way
        return enemyTable, #enemyTable
    end

    --- The enemies in the player's frontal rectangle (a line spell), by the server's rule (see
    -- getEnemiesInRect)
    -- @function enemies.rect.get
    -- @number range How far the rectangle reaches, in yards
    -- @number width Its full width, in yards (the spell's Width)
    -- @bool checkNoCombat Count units not in combat too
    -- @treturn table The units, the same table as enemies.yards<range>r
    -- @treturn number How many
    enemies.rect.get = function(range, width, checkNoCombat)
        local count, units = br.engines.enemiesEngineFunctions:getEnemiesInRect(range, width, checkNoCombat)
        -- The list kept as enemies.yards<range>r: the engine reuses its table on the next call
        return br.functions.misc:setEnemiesVariable("player", range, checkNoCombat, false, "r", units, count), count
    end
end
